const $=s=>document.querySelector(s),key='gelanggang-64-v1';
const TOURNAMENT={rinks:8,groupWavesByDay:[8,6,8,6],overnight:false};
const GROUPS=['A','B','C','D','E','F','G','H'];
const teamGroup=id=>GROUPS[Math.floor(id/8)];
const isGroup=code=>/^G[A-H]$/.test(code);
function demoEnds(seedValue,knockout=false){let n=seedValue+97,s=[0,0],ends=[];for(let i=0;i<13;i++){n=(Math.imul(n,1664525)+1013904223)>>>0;let side=(n>>>15)%2,shots=1+(n>>>5)%4;s[side]+=shots;ends.push([...s])}if(knockout&&s[0]===s[1]){s[seedValue%2]++;ends.push([...s])}return ends}
function demoDate(offset){let d=new Date('2027-01-28T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10)}
function waveMinutes(wave,overnight=false){return 600+wave*90+((overnight?wave>=7:wave>=2)?30:0)}
function waveTime(wave,overnight=false){let minutes=waveMinutes(wave,overnight)%1440;return String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0')}
function groupMinutes(slot,day,overnight=false){return demoDate(day)==='2027-01-29'?(slot===0?600:840+(slot-1)*90):waveMinutes(slot,overnight)}
function groupTime(slot,day,overnight=false){let minutes=groupMinutes(slot,day,overnight)%1440;return String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0')}
function groupWave(wave,config){let day=0;while(day<config.groupWavesByDay.length&&wave>=config.groupWavesByDay[day]){wave-=config.groupWavesByDay[day];day++}return {day,slot:wave}}
function seed(){let config={...TOURNAMENT},base=['Harimau','Singa','Kancil','Helang','Rajawali','Merpati','Garuda','Panther'];let teams=Array.from({length:64},(_,i)=>i<8?base[i]:base[i%8]+' '+GROUPS[Math.floor(i/8)]),matches=[];const add=m=>{m.ends=demoEnds(matches.length+1,!isGroup(m.group));m.score=[...m.ends.at(-1)];matches.push(m);return m};
 for(let round=0;round<7;round++)for(let g=0;g<8;g++){let rotation=Array.from({length:8},(_,i)=>g*8+i);for(let r=0;r<round;r++)rotation=[rotation[0],rotation[7],...rotation.slice(1,7)];for(let p=0;p<4;p++){let slot=round*32+g*4+p,wave=Math.floor(slot/config.rinks),position=groupWave(wave,config),date=demoDate(position.day+Math.floor(groupMinutes(position.slot,position.day,config.overnight)/1440));add({id:'g-'+GROUPS[g]+'-'+round+'-'+p,group:'G'+GROUPS[g],round:round+1,a:rotation[p],b:rotation[7-p],date,time:groupTime(position.slot,position.day,config.overnight),rink:slot%config.rinks+1})}}
 const rank=g=>{let rows=Array.from({length:8},(_,i)=>({id:GROUPS.indexOf(g)*8+i,pts:0,for:0,against:0}));matches.filter(m=>m.group==='G'+g).forEach(m=>[0,1].forEach(side=>{let r=rows.find(r=>r.id===[m.a,m.b][side]),a=m.score[side],b=m.score[1-side];r.pts+=a>b?2:a===b?1:0;r.for+=a;r.against+=b}));return rows.sort((a,b)=>b.pts-a.pts||(b.for-b.against)-(a.for-a.against)||b.for-a.for||a.id-b.id)};
 const resolve=src=>src.group?rank(src.group)[src.rank].id:(()=>{let m=matches.find(m=>m.id===src.match),win=m.score[0]>m.score[1]?m.a:m.b;return src.outcome==='loser'?(win===m.a?m.b:m.a):win})();
 const groupDays=config.groupWavesByDay.length;config.groupDays=groupDays;config.totalDays=groupDays+1;const ko=(group,id,aSource,bSource,wave,rink,day=groupDays-1)=>add({id,group,aSource,bSource,a:resolve(aSource),b:resolve(bSource),date:demoDate(day),time:waveTime(wave),rink});
 let index=0;for(let g=0;g<8;g+=2)for(let r=0;r<4;r++){let first=r<2?g:g+1,second=r<2?g+1:g,pos=r%2;ko('R32','r32-'+index,{group:GROUPS[first],rank:pos},{group:GROUPS[second],rank:3-pos},config.groupWavesByDay.at(-1)+Math.floor(index/config.rinks),index%config.rinks+1);index++}
 for(const [phase,count,prev,offset] of [['R16',8,'r32',0],['QF',4,'r16',1],['SF',2,'qf',2]]){for(let i=0;i<count;i++)ko(phase,phase.toLowerCase()+'-'+i,{match:prev+'-'+(i*2),outcome:'winner'},{match:prev+'-'+(i*2+1),outcome:'winner'},offset,i%config.rinks+1,groupDays)}let wave=3;
 ko('P','p',{match:'sf-0',outcome:'loser'},{match:'sf-1',outcome:'loser'},wave,2,groupDays);ko('F','f',{match:'sf-0',outcome:'winner'},{match:'sf-1',outcome:'winner'},wave,1,groupDays);return {version:64,calendarRevision:4,settings:config,teams,matches};}
function migrateCalendar(saved){if(saved.version!==64||saved.calendarRevision===4)return false;const plan=seed(),byId=new Map(plan.matches.map(m=>[m.id,m]));saved.matches.forEach(m=>{const next=byId.get(m.id);if(next){m.date=next.date;m.time=next.time;m.rink=next.rink}});saved.settings=plan.settings;saved.calendarRevision=4;return true}
let state;try{state=JSON.parse(localStorage.getItem(key));if(state?.version!==64){state=seed();const old=JSON.parse(localStorage.getItem('gelanggang-v2'));if(old?.teams&&old?.profiles){state.legacyProfiles=old.profiles;old.teams.slice(0,6).forEach((n,i)=>state.teams[i]=n)}}}catch{state=seed()}if(migrateCalendar(state)){try{localStorage.setItem(key,JSON.stringify(state))}catch{}}let view='overview',filter='all',editing=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const name=id=>id==null?'Menunggu kelayakan':esc(state.teams[id]);
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Penyimpanan pelayar tidak tersedia. Eksport CSV untuk salinan.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
function standings(g){let rows=Array.from({length:8},(_,i)=>({id:GROUPS.indexOf(g)*8+i,played:0,w:0,d:0,l:0,for:0,against:0,pts:0}));state.matches.filter(m=>m.group==='G'+g&&m.score).forEach(m=>[0,1].forEach(side=>{let r=rows.find(r=>r.id===[m.a,m.b][side]);if(!r)return;let a=m.score[side],b=m.score[1-side];r.played++;r.for+=a;r.against+=b;r.w+=a>b;r.d+=a===b;r.l+=a<b;r.pts+=a>b?2:a===b?1:0}));return rows.sort((a,b)=>b.pts-a.pts||(b.for-b.against)-(a.for-a.against)||b.for-a.for||a.id-b.id)}
function resolveSource(src){if(src.group){let league=state.matches.filter(m=>m.group==='G'+src.group);return league.length===28&&league.every(m=>m.score)?standings(src.group)[src.rank]?.id??null:null}let m=state.matches.find(m=>m.id===src.match);if(!m?.score||m.score[0]===m.score[1])return null;let win=m.score[0]>m.score[1]?m.a:m.b;return src.outcome==='loser'?(win===m.a?m.b:m.a):win}
function sync(){state.matches.filter(m=>!isGroup(m.group)).forEach(m=>{let a=resolveSource(m.aSource),b=resolveSource(m.bSource);if(m.a!==a||m.b!==b){m.a=a;m.b=b;m.score=null;m.ends=null;m.endNotes=[]}})}
const label=m=>isGroup(m.group)?'Kumpulan '+m.group.slice(1):({R32:'Top 32',R16:'Top 16',QF:'Suku Akhir',SF:'Separuh Akhir',F:'Akhir',P:'Ke-3/4'}[m.group]||m.group);
function groupTable(g){return `<article class="panel"><div class="panel-head"><h3>Kumpulan ${g}</h3><span>8 pasukan · Top 4 layak</span></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Pasukan</th><th>Main</th><th>M</th><th>S</th><th>K</th><th>Shot +/−</th><th>Beza</th><th>Mata</th></tr></thead><tbody>${standings(g).map((r,i)=>`<tr class="${i<4?'qual':''}"><td>${i+1}</td><td class="team-name">${summaryTeam(r.id)}</td><td>${r.played}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.for}/${r.against}</td><td>${r.for-r.against>0?'+':''}${r.for-r.against}</td><td class="points">${r.pts}</td></tr>`).join('')}</tbody></table></div></article>`}
const demoMatchDate='2027-01-28';
function validMatchDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;let d=new Date(value+'T12:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===value}
function matchDateInfo(match){const date=validMatchDate(match.date||'')?match.date:demoMatchDate;const d=new Date(date+'T12:00:00+08:00');return {iso:date,date:new Intl.DateTimeFormat('ms-MY',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}).format(d),day:new Intl.DateTimeFormat('ms-MY',{weekday:'long',timeZone:'Asia/Kuala_Lumpur'}).format(d)}}
function matchNumber(match){const index=state.matches.findIndex(m=>m.id===match.id);return (index+1)+'/'+state.matches.length}
function matchInfo(match){const d=matchDateInfo(match);const item=(label,value)=>`<div><dt>${label}</dt><dd>${value}</dd></div>`;return `<dl class="match-info-grid">${item('No. perlawanan',matchNumber(match))}${item('Peringkat',label(match))}${item(match.date?'Tarikh':'Tarikh (demo)',ADMIN?`<input type="date" id="matchDateInput" aria-label="Tarikh perlawanan" value="${d.iso}" required>`:d.date)}${item('Hari',`<span id="matchDay">${d.day}</span>`)}${item('Masa mula',match.time)}${item('Rink','Rink '+match.rink)}${item('Jumlah Ends','13 ends'+(match.ends?.length>13?' + '+(match.ends.length-13)+' extra':''))}${item('Tempoh','1 jam 30 minit')}</dl>`}

function scheduleTeam(match,side){const id=[match.a,match.b][side],outcome=endsOutcome(match.score,side);return `<div class="matchface-team outcome-${outcome}"><div class="matchface-crest">${id==null?'<span class="matchface-empty" aria-label="Pasukan belum ditentukan">?</span>':teamLogo(id)+teamFlag(id)}</div><strong>${name(id)}</strong><span class="matchface-underline" aria-hidden="true"></span><span class="sr-only">${endsResultLabel(outcome)}</span></div>`}
function cardTime(time){const [hours,minutes]=time.split(':').map(Number);return (hours%12||12)+':'+String(minutes).padStart(2,'0')+(hours<12?'am':'pm')}
function scheduleCards(matches,headingOverride='',showHeading=true){return `${showHeading?`<div class="matchface-heading"><h3>${headingOverride||(isGroup(filter)?'Kumpulan '+filter.slice(1):filter==='KO'?'Kalah mati':'Semua perlawanan')}</h3><span>${matches.filter(m=>m.score).length}/${matches.length} selesai</span></div>`:''}<div class="matchface-grid" role="list">${matches.map(match=>{const date=matchDateInfo(match),ready=match.a!=null&&match.b!=null;return `<article class="matchface-card" role="listitem"><div class="matchface-top"><span class="matchface-number">M${state.matches.findIndex(m=>m.id===match.id)+1} <small>· ${matchNumber(match)}</small></span><span class="matchface-status">${match.score?'Selesai':ready?'Dijadualkan':'Menunggu'}</span><span class="matchface-stage">${label(match)}</span></div><div class="matchface-versus">${scheduleTeam(match,0)}<div class="matchface-score" aria-label="Keputusan ${match.score?match.score.join(' berbalas '):'belum tersedia'}"><b>${match.score?match.score[0]:'—'}</b><span>:</span><b>${match.score?match.score[1]:'—'}</b></div>${scheduleTeam(match,1)}</div><div class="matchface-meta" tabindex="0" role="region" aria-label="Maklumat perlawanan; leret jika perlu"><span>${date.date} (${date.day}) ·${cardTime(match.time)} · Rink ${match.rink}</span></div><div class="matchface-actions"><button type="button" data-edit="${match.id}" ${ready?'':'disabled'} aria-label="Buka Remarks ${name(match.a)} lwn ${name(match.b)}">Remarks</button></div></article>`}).join('')}</div>`}

function matchTable(matches){if(view==='schedule')return scheduleCards(matches);return `<div class="fixture-board"><div class="fixture-list-header" aria-hidden="true"><span>Masa & rink</span><span>Perlawanan & keputusan</span><span>Butiran</span></div><div class="fixture-list" role="list">${matches.map(match=>`<article class="fixture-card" role="listitem"><h3 class="sr-only">${name(match.a)} lwn ${name(match.b)}</h3><div class="fixture-meta"><span class="fixture-match-number">No. ${matchNumber(match)}</span><span class="fixture-date">${matchDateInfo(match).date}<br>${matchDateInfo(match).day}${match.date?'':' · Demo'}</span><div class="fixture-time"><time datetime="${match.time}">${match.time}</time><span>90 minit</span></div><span class="fixture-round">${label(match)}</span><span class="fixture-rink">Rink ${match.rink}</span></div><div class="fixture-scoreboard">${[match.a,match.b].map((id,side)=>`<div class="fixture-score-row ${match.score&&match.score[side]>match.score[1-side]?'fixture-winner':''}">${id==null?'<span class="fixture-pending">Menunggu kelayakan</span>':summaryTeam(id)}<span class="fixture-shot" aria-label="${name(id)}, ${match.score?match.score[side]+' shot':'belum ada skor'}">${match.score?match.score[side]:'—'}</span></div>`).join('')}</div><div class="fixture-details"><span class="fixture-status ${match.score?'is-complete':''}">${match.score?'Selesai':'Belum dimainkan'}</span><button type="button" data-edit="${match.id}" ${match.a==null||match.b==null?'disabled':''} aria-label="Buka remarks (keputusan 13 ends): ${name(match.a)} lwn ${name(match.b)}">Remarks</button></div></article>`).join('')}</div></div>`}
function card(m){return `<div class="match-card"><div class="match-meta"><span>${label(m)}</span><span>${m.time} · Rink ${m.rink}</span></div>${[m.a,m.b].map((id,i)=>`<div class="match-row ${m.score&&m.score[i]>m.score[1-i]?'winner':''}"><span>${name(id)}</span><b>${m.score?m.score[i]:'—'}</b></div>`).join('')}<button data-edit="${m.id}" ${m.a==null||m.b==null?'disabled':''}>Remarks</button></div>`}
const knockoutRounds=[['R32','Top 32'],['R16','Top 16'],['QF','Suku Akhir'],['SF','Separuh Akhir'],['P','Ke-3/4'],['F','Akhir']];
function knockoutMatches(round='all'){return state.matches.filter(m=>!isGroup(m.group)&&(round==='all'||m.group===round))}
function knockoutCard(match){return `<div class="ko-node"><div class="ko-node-label">M${state.matches.findIndex(m=>m.id===match.id)+1} · ${match.time} · Rink ${match.rink}</div><button type="button" class="ko-mini" data-edit="${match.id}" ${match.a==null||match.b==null?'disabled':''} aria-label="Remarks: ${name(match.a)} lwn ${name(match.b)}">${[match.a,match.b].map((id,side)=>`<span class="ko-mini-row ko-${endsOutcome(match.score,side)}">${id==null?'<span class="ko-mini-identity">Menunggu kelayakan</span>':`<span class="ko-mini-identity">${teamLogo(id)}${teamFlag(id)}<strong>${name(id)}</strong></span>`}<b>${match.score?match.score[side]:'—'}</b></span>`).join('')}</button></div>`}
function knockoutBracket(){const order=['R32','R16','QF','SF','F','P'];return `<nav class="ko-jump" aria-label="Lompat pusingan bracket">${knockoutRounds.map(([id,title])=>`<button type="button" data-round-jump="${id}" aria-pressed="${id==='R32'}" class="${id==='R32'?'active':''}">${title}</button>`).join('')}</nav><p class="ko-help">Pilih pusingan untuk lompat · Leret ke sisi untuk melihat semua peringkat · Tekan perlawanan untuk Remarks.</p><div class="ko-bracket-scroll" tabindex="0" role="region" aria-label="Bracket kalah mati bermula Top 32"><div class="ko-bracket-track">${order.map(id=>{let matches=knockoutMatches(id),title=knockoutRounds.find(r=>r[0]===id)[1];return `<section class="ko-column ${id==='P'?'ko-placement':''}" data-round-column="${id}"><h3>${title}</h3><p class="ko-column-count">${matches.length} perlawanan</p><div class="ko-column-matches">${matches.length?matches.map(knockoutCard).join(''):'<div class="ko-empty"><b>Tiada perlawanan</b><p>Peringkat ini tidak digunakan dalam format semasa.</p></div>'}</div>${id==='F'?knockoutChampion():''}</section>`}).join('')}</div></div>`}
function knockoutChampion(){const final=knockoutMatches('F')[0];if(!final?.score)return '';let winner=final.score[0]>final.score[1]?final.a:final.b;return `<div class="ko-champion"><span>JUARA</span>${teamLogo(winner)}<b>${name(winner)}</b>${teamFlag(winner)}</div>`}
function bindKnockout(){const scroll=$('.ko-bracket-scroll');document.querySelectorAll('[data-round-jump]').forEach(b=>b.onclick=()=>{const target=document.querySelector('[data-round-column="'+b.dataset.roundJump+'"]');if(target&&scroll){scroll.scrollTo({left:target.offsetLeft-scroll.querySelector('.ko-bracket-track').offsetLeft,behavior:'smooth'});document.querySelectorAll('[data-round-jump]').forEach(other=>{other.classList.toggle('active',other===b);other.setAttribute('aria-pressed',String(other===b))})}});if(scroll){let dragging=false,startX=0,startScroll=0;scroll.onpointerdown=e=>{if(e.pointerType==='touch'||e.button!==0||e.target.closest('button'))return;dragging=true;startX=e.clientX;startScroll=scroll.scrollLeft;scroll.setPointerCapture(e.pointerId);scroll.classList.add('is-dragging')};scroll.onpointermove=e=>{if(dragging)scroll.scrollLeft=startScroll-(e.clientX-startX)};scroll.onpointerup=scroll.onpointercancel=()=>{dragging=false;scroll.classList.remove('is-dragging')}}}


const ADMIN=true;
const regions=['Johor','Kedah','Kelantan','Melaka','Negeri Sembilan','Pahang','Pulau Pinang','Perak','Perlis','Sabah','Sarawak','Selangor','Terengganu','Wilayah Persekutuan'];
const teamDefaults=['Wilayah Persekutuan','Selangor','Johor','Perak','Sabah','Sarawak'];
const demoPlayers=[['Amir Hakimi','Farid Azlan','Hafiz Roslan'],['Aiman Syafiq','Fikri Zainal','Danish Irfan'],['Hakim Faiz','Rizal Adli','Azri Hamdan'],['Faiz Rahman','Akmal Haris','Zul Ariff'],['Firdaus Adam','Syahmi Rafiq','Imran Haziq'],['Nabil Arif','Rafiq Aizat','Irfan Shah']];
function ensureProfiles(){if(!state.profiles)state.profiles=state.teams.map((n,i)=>state.legacyProfiles?.[i]||({region:regions[i%regions.length],logo:'',flag:'',captain:2,players:Array.from({length:3},(_,j)=>({name:i<6?demoPlayers[i][j]:'Pemain '+teamGroup(i)+(i%8+1)+'-'+(j+1),role:['Lead','Second','Skip'][j],number:String(j+1),region:'',flag:''}))}));delete state.legacyProfiles;}
function flagPath(region){return 'flags/'+region.toLowerCase().replaceAll(' ','-')+'.svg'}
function logoSvg(i){const colors=['#112b68','#b5293d','#18397c','#9d2439','#27395e','#ac3841'];return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80"><path fill="${colors[i%colors.length]}" d="M8 8h64v40Q67 66 40 77 13 66 8 48Z"/><circle cx="40" cy="32" r="17" fill="none" stroke="#f5ce48" stroke-width="2"/><circle cx="40" cy="32" r="10" fill="none" stroke="#f5ce48"/><text x="40" y="63" text-anchor="middle" fill="white" font-family="sans-serif" font-size="13">${teamGroup(i)}${i%8+1}</text></svg>`)}
function img(src,alt,cls){return `<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`}
function teamLogo(i,p=state.profiles[i]){return img(p.logo||logoSvg(i),'Logo '+state.teams[i],'profile-logo')}
function teamFlag(i,p=state.profiles[i]){return img(p.flag||flagPath(p.region),'Bendera '+p.region,'state-flag')}
let teamReportScope='group';
function matchEndsPlayed(match){return match.score?(match.ends?.length||13):0}
function tournamentEnds(){const games=state.matches.filter(m=>m.score);return {total:games.reduce((sum,m)=>sum+matchEndsPlayed(m),0),regular:games.length*13,extra:games.reduce((sum,m)=>sum+Math.max(0,matchEndsPlayed(m)-13),0)}}
function teamReport(id,scope='group'){const matches=state.matches.filter(m=>(m.a===id||m.b===id)&&(scope==='all'||scope==='group'&&isGroup(m.group)||scope==='ko'&&!isGroup(m.group))).slice().sort((a,b)=>(a.date+'T'+a.time).localeCompare(b.date+'T'+b.time)||state.matches.indexOf(a)-state.matches.indexOf(b));let r={matches,played:0,w:0,l:0,d:0,shotFor:0,shotAgainst:0,ends:0,extra:0};r.results=[];matches.forEach(m=>{if(!m.score)return;let side=m.a===id?0:1,own=m.score[side],against=m.score[1-side],outcome=own>against?'win':own<against?'lose':'draw';r.played++;r[outcome==='win'?'w':outcome==='lose'?'l':'d']++;r.shotFor+=own;r.shotAgainst+=against;r.ends+=matchEndsPlayed(m);r.extra+=Math.max(0,matchEndsPlayed(m)-13);r.results.push({match:m,opponent:side===0?m.b:m.a,own,against,difference:own-against,outcome,points:isGroup(m.group)?own>against?2:own===against?1:0:null})});r.difference=r.shotFor-r.shotAgainst;r.winRate=r.played?r.w/r.played*100:0;r.averageFor=r.played?r.shotFor/r.played:0;return r}
function signedShot(value){return value>0?'+'+value:String(value)}
function teamGroupSnapshot(id){const g=teamGroup(id),rows=standings(g),rank=rows.findIndex(r=>r.id===id)+1,row=rows.find(r=>r.id===id),ready=state.matches.filter(m=>m.group==='G'+g).every(m=>m.score);return {g,rank,row,ready,status:ready?rank<=4?'Layak Top 32':'Tersingkir kumpulan':'Kelayakan belum disahkan'}}
function teamFinalPlacement(id){const belongs=m=>m.a===id||m.b===id,complete=m=>m?.score&&m.score[0]!==m.score[1],won=m=>m.score[m.a===id?0:1]>m.score[m.a===id?1:0];const base={finalized:false,rank:null,range:null,tier:'live',seal:'—',label:'Status kejohanan',match:null};const final=state.matches.find(m=>m.group==='F'&&belongs(m)),third=state.matches.find(m=>m.group==='P'&&belongs(m));if(complete(final)){const rank=won(final)?1:2;return {...base,finalized:true,rank,tier:rank===1?'gold':'silver',seal:String(rank),label:'Kedudukan akhir kejohanan',title:rank===1?'Johan':'Naib Johan',description:rank===1?'Menjuarai perlawanan akhir.':'Finalis kejohanan.',match:final}}
if(complete(third)){const rank=won(third)?3:4;return {...base,finalized:true,rank,tier:rank===3?'bronze':'fourth',seal:String(rank),label:'Kedudukan akhir kejohanan',title:'Tempat ke-'+rank,description:'Pencapaian Separuh Akhir; kedudukan ditentukan melalui perlawanan ke-3/4.',match:third}}
const sf=state.matches.find(m=>m.group==='SF'&&belongs(m));if(complete(sf)&&!won(sf))return {...base,title:'Penentuan ke-3/4',description:'Tersingkir di Separuh Akhir. Kedudukan akhir menunggu keputusan perlawanan ke-3/4.'};
for(const [phase,title,range,tier] of [['QF','Suku Akhir','5–8','quarter'],['R16','Top 16','9–16','top16'],['R32','Top 32','17–32','top32']]){const match=state.matches.find(m=>m.group===phase&&belongs(m));if(complete(match)&&!won(match))return {...base,finalized:true,range,tier,seal:range,label:'Pencapaian akhir kejohanan',title,description:'Tersingkir di '+title+'. Julat kedudukan '+range+'; tiada penentuan tempat tepat.',match}}
const group=teamGroupSnapshot(id);if(group.ready&&group.rank>4)return {...base,finalized:true,range:'33–64',tier:'group',seal:'33–64',label:'Pencapaian akhir kejohanan',title:'Tersingkir kumpulan',description:'Kumpulan '+group.g+': kedudukan '+group.rank+'/8. Julat kejohanan 33–64; tiada penentuan silang kumpulan.'};
if(final)return {...base,title:'Finalis',description:'Kedudukan Johan / Naib Johan belum diputuskan.'};if(third)return {...base,title:'Penentuan ke-3/4',description:'Kedudukan akhir belum diputuskan.'};for(const [phase,title] of [['SF','Separuh Akhir'],['QF','Suku Akhir'],['R16','Top 16'],['R32','Top 32']])if(state.matches.some(m=>m.group===phase&&belongs(m)))return {...base,title,description:'Masih dalam kejohanan. Kedudukan akhir belum diputuskan.'};return {...base,title:group.ready?'Layak Top 32':'Peringkat kumpulan',description:'Kedudukan akhir belum diputuskan.'}}
function placementRound(place){if(place.rank===1||place.rank===2||place.title==='Finalis')return 'Akhir';if(place.rank===3||place.rank===4||place.title==='Penentuan ke-3/4')return 'Separuh Akhir · Ke-3/4';if(place.title==='Tersingkir kumpulan'||place.title==='Peringkat kumpulan')return 'Peringkat kumpulan';return place.title}
function teamPlacementCard(id,profile=state.profiles[id]){const place=teamFinalPlacement(id);return `<section class="placement-hero placement-${place.tier}" aria-label="${place.label}"><div class="placement-content"><span class="placement-eyebrow">${place.label}</span><h3>${place.title}</h3>${placementRound(place)!==place.title?`<span class="placement-round">${placementRound(place)}</span>`:''}<p>${place.description}</p></div><div class="placement-seal ${place.range?'is-range':''}" aria-label="${place.rank?'Tempat '+place.rank:place.range?'Julat '+place.range:'Belum ditentukan'}"><b>${place.seal}</b><span>${place.rank?'TEMPAT':place.range?'JULAT':'SEMASA'}</span></div><div class="placement-identity">${teamLogo(id,profile)}${teamFlag(id,profile)}<span>${esc(profile.region)} · Kumpulan ${teamGroup(id)} · 3 pemain</span></div>${place.match?`<div class="placement-evidence"><span>${label(place.match)} · ${place.match.score[place.match.a===id?0:1]} – ${place.match.score[place.match.a===id?1:0]} lwn ${name(place.match.a===id?place.match.b:place.match.a)}</span><button type="button" data-placement-remarks="${place.match.id}">Lihat keputusan</button></div>`:''}</section>`}
function bindTeamPlacement(){const panel=$('#teamPlacement');if(panel)panel.querySelectorAll('[data-placement-remarks]').forEach(b=>b.onclick=()=>openMatch(b.dataset.placementRemarks))}

function teamResultsHtml(id,report){return `<details class="team-history" data-team-history><summary>Detail setiap perlawanan <span>${report.matches.length} perlawanan</span></summary><div class="team-results">${report.matches.length?report.matches.map(m=>{const side=m.a===id?0:1,opponent=side===0?m.b:m.a,played=!!m.score,type=endsOutcome(m.score,side),own=m.score?.[side],against=m.score?.[1-side],difference=played?own-against:null,points=played&&isGroup(m.group)?own>against?2:own===against?1:0:null,d=matchDateInfo(m);return `<article class="team-result-card"><div class="team-result-top"><span>No. ${matchNumber(m)} · ${label(m)}${m.round?' · Pusingan '+m.round:''}</span><b class="team-outcome ${type}">${endsResultLabel(type)}</b></div><div class="team-result-main"><div class="team-opponent"><span>Lawan</span>${opponent==null?'Menunggu kelayakan':`<div>${teamLogo(opponent)}${teamFlag(opponent)}<strong>${name(opponent)}</strong></div>`}</div><div class="team-own-score"><b>${played?own+' – '+against:'—'}</b><span>Shot + / Shot −</span></div></div><div class="team-result-stats"><span>Beza <b class="shot-${difference>0?'positive':difference<0?'negative':'even'}">${played?signedShot(difference):'—'}</b></span>${isGroup(m.group)?`<span>Mata liga <b>${points??'—'}</b></span>`:'<span>Kalah mati</span>'}<span>Ends dimainkan <b>${matchEndsPlayed(m)}</b>${matchEndsPlayed(m)>13?' (+'+(matchEndsPlayed(m)-13)+' extra)':''}</span></div><p class="team-result-time">${d.date} (${d.day}) ·${cardTime(m.time)} · Rink ${m.rink}</p><div class="team-result-actions"><button type="button" data-team-remarks="${m.id}" ${m.a==null||m.b==null?'disabled':''}>Remarks</button></div></article>`}).join(''):'<p class="note">Tiada perlawanan pasukan pada peringkat ini.</p>'}</div></details>`}
function teamAnalyticsBody(id){const r=teamReport(id,teamReportScope),all=teamReport(id,'all'),group=teamGroupSnapshot(id),form=r.results.slice(-5);return `<div class="team-report-heading"><h3>Statistik & rekod pasukan</h3><span>Jumlah keseluruhan: <b>${all.ends} Ends</b></span></div><div class="team-report-tabs" role="group" aria-label="Skop statistik pasukan">${[['group','Kumpulan'],['ko','Kalah Mati'],['all','Keseluruhan']].map(([key,label])=>`<button type="button" data-team-scope="${key}" class="${teamReportScope===key?'active':''}" aria-pressed="${teamReportScope===key}">${label}</button>`).join('')}</div><div class="team-group-snapshot"><span>Kumpulan ${group.g} · <b>${group.ready?'Kedudukan':'Sementara'} ${group.rank}/8</b></span><span>Mata liga: <b>${group.row.pts}</b></span><span class="${group.ready&&group.rank<=4?'qualified':''}">${group.status}</span></div><div class="record team-report-wld"><span class="team-report-win"><b>${r.w}</b>Menang</span><span class="team-report-lose"><b>${r.l}</b>Kalah</span><span class="team-report-draw"><b>${r.d}</b>Seri</span><span><b>${r.played}</b>Main</span></div><div class="team-kpis"><div><span>Shot +</span><strong>${r.shotFor}</strong><small>Diperoleh</small></div><div><span>Shot −</span><strong>${r.shotAgainst}</strong><small>Shot lawan</small></div><div><span>Beza shot</span><strong class="shot-${r.difference>0?'positive':r.difference<0?'negative':'even'}">${signedShot(r.difference)}</strong><small>Shot + tolak Shot −</small></div><div><span>Ends dimainkan</span><strong>${r.ends}</strong><small>${r.played*13} biasa + ${r.extra} extra</small></div><div><span>Kadar menang</span><strong>${r.winRate.toFixed(1)}%</strong><small>${r.w} daripada ${r.played} perlawanan</small></div><div><span>Purata Shot +</span><strong>${r.averageFor.toFixed(1)}</strong><small>Setiap perlawanan selesai</small></div></div><div class="team-form"><span>5 keputusan terkini</span><div>${form.length?form.map(result=>`<span class="team-form-chip ${result.outcome}" title="${name(result.opponent)}: ${result.own}–${result.against}" aria-label="${endsResultLabel(result.outcome)} lawan ${name(result.opponent)}, ${result.own} berbalas ${result.against}">${result.outcome==='win'?'M':result.outcome==='lose'?'K':'S'}</span>`).join(''):'<span>Belum ada keputusan</span>'}</div></div><p class="team-report-note">Statistik di atas mengikut skop yang dipilih. Mata liga dan kedudukan hanya untuk kumpulan. Ends dan shot dikira daripada perlawanan selesai; extra ends termasuk dalam jumlah Ends.</p>${teamResultsHtml(id,r)}`}
function teamAnalytics(id){return `<section id="teamAnalytics" class="team-analytics">${teamAnalyticsBody(id)}</section>`}
function refreshTeamAnalytics(){const placement=$('#teamPlacement');if(placement&&profileId!=null)placement.innerHTML=teamPlacementCard(profileId,profileDraft||state.profiles[profileId]);const panel=$('#teamAnalytics');if(!panel||profileId==null)return;const expanded=panel.querySelector('[data-team-history]')?.open;panel.innerHTML=teamAnalyticsBody(profileId);if(expanded)panel.querySelector('[data-team-history]').open=true;bindTeamAnalytics()}
function bindTeamAnalytics(){bindTeamPlacement();const panel=$('#teamAnalytics');if(!panel)return;panel.querySelectorAll('[data-team-scope]').forEach(b=>b.onclick=()=>{teamReportScope=b.dataset.teamScope;refreshTeamAnalytics()});panel.querySelectorAll('[data-team-remarks]').forEach(b=>b.onclick=()=>openMatch(b.dataset.teamRemarks))}
function teamCompactFacts(id){const r=teamReport(id,'group'),g=teamGroupSnapshot(id),all=teamReport(id,'all');return `<div class="team-compact-facts"><span>Kumpulan: <b>#${g.rank}/8 · ${g.row.pts} mata</b></span><span>Shot: <b>${r.shotFor}/${r.shotAgainst} (${signedShot(r.difference)})</b></span><span>Jumlah Ends: <b>${all.ends}</b></span></div>`}

function record(i){let r={played:0,w:0,l:0,d:0,shotFor:0,shotAgainst:0};state.matches.filter(m=>m.score&&(m.a===i||m.b===i)).forEach(m=>{let j=m.a===i?0:1,x=m.score[j],y=m.score[1-j];r.played++;r.w+=x>y;r.l+=x<y;r.d+=x===y;r.shotFor+=x;r.shotAgainst+=y});return r}
function recordHtml(i){let r=record(i);return `<div class="record"><span><b>${r.w}</b>Win</span><span><b>${r.l}</b>Lose</span><span><b>${r.d}</b>Draw</span><span><b>${r.played}</b>Main</span></div>`}
let rosterMode='teams',rosterSearch='',rosterGroup='all',rosterRegion='all',profileDraft=null,profileId=null;
function roster(){ensureProfiles();return `<div class="section-title"><div><div class="eyebrow">DIREKTORI KEJOHANAN</div><h2 style="margin-top:9px">Pasukan</h2><p>64 pasukan · 3 pemain setiap pasukan · Format triples</p></div><span class="tag">${ADMIN?'Admin · Boleh edit':'Awam · Baca sahaja'}</span></div><div class="roster-controls"><label class="sr-only" for="rosterSearch">Cari pasukan</label><input id="rosterSearch" type="search" placeholder="Cari pasukan…" value="${esc(rosterSearch)}"><label class="sr-only" for="rosterGroup">Kumpulan</label><select id="rosterGroup"><option value="all">Semua kumpulan</option>${GROUPS.map(g=>`<option value="${g}" ${rosterGroup===g?'selected':''}>Kumpulan ${g}</option>`).join('')}</select><label class="sr-only" for="rosterRegion">Negeri</label><select id="rosterRegion"><option value="all">Semua negeri</option>${regions.map(r=>`<option ${r===rosterRegion?'selected':''}>${r}</option>`).join('')}</select></div><div id="rosterResults">${rosterResults()}</div><p class="note">Statistik Win / Lose / Draw ialah rekod pasukan daripada semua perlawanan yang selesai, termasuk kalah mati.</p>`}
function rosterResults(){let ids=state.teams.map((n,i)=>i).filter(i=>{let p=state.profiles[i],g=teamGroup(i),q=rosterSearch.toLowerCase().trim();return(rosterGroup==='all'||rosterGroup===g)&&(rosterRegion==='all'||rosterRegion===p.region)&&(!q||state.teams[i].toLowerCase().includes(q)||p.region.toLowerCase().includes(q))});if(!ids.length)return '<div class="panel empty-roster">Tiada pasukan sepadan dengan carian.</div>';return `<div class="roster-grid team-only-grid">${ids.map(i=>{let p=state.profiles[i];return `<article class="roster-card"><div class="roster-cover"><span class="pill">KUMPULAN ${teamGroup(i)} · ${i%8+1}</span>${teamFlag(i)}</div><div class="roster-body"><div class="team-identity">${teamLogo(i)}<div><h3>${name(i)}</h3><p>${esc(p.region)}</p></div></div>${recordHtml(i)}${teamCompactFacts(i)}<div class="team-lineup-label">PEMAIN PASUKAN <span>3 pemain</span></div><div class="team-lineup">${p.players.map((pl,j)=>`<div class="team-lineup-player">${playerPhoto(pl)}<span class="lineup-role">${esc(pl.role)}</span><strong>${esc(pl.name)}</strong><span class="lineup-number">#${esc(pl.number)}${p.captain===j?' · Kapten':''}</span></div>`).join('')}</div><button class="profile-open" data-profile="${i}">${ADMIN?'Lihat / edit pasukan':'Lihat pasukan'}</button></div></article>`}).join('')}</div>`}
function bindRoster(){if($('#rosterSearch'))$('#rosterSearch').oninput=e=>{rosterSearch=e.target.value;$('#rosterResults').innerHTML=rosterResults();bindProfileButtons()};['Group','Region'].forEach(k=>{let input=$('#roster'+k);if(input)input.onchange=()=>{if(k==='Group')rosterGroup=input.value;else rosterRegion=input.value;$('#rosterResults').innerHTML=rosterResults();bindProfileButtons()}});bindProfileButtons()}
function bindProfileButtons(){bindPlayerButtons();document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>openProfile(+b.dataset.profile))}
function regionSelect(value,field,inherit=false){return `<select data-field="${field}">${inherit?'<option value="">Ikut negeri pasukan</option>':''}${regions.map(r=>`<option ${r===value?'selected':''}>${r}</option>`).join('')}</select>`}
function field(label,value,path,extra=''){return `<label>${label}<input data-field="${path}" value="${esc(value)}" maxlength="60" required ${extra}></label>`}
function upload(label,target){return `<label class="upload-label">${label}<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="${target}"></label><button type="button" class="small-btn" data-remove="${target}">Guna lalai</button>`}
function openProfile(i){ensureProfiles();teamReportScope='group';profileId=i;profileDraft=JSON.parse(JSON.stringify(state.profiles[i]));profileDraft.teamName=state.teams[i];let d=$('#profileDialog');if(!d){d=document.createElement('dialog');d.id='profileDialog';document.body.appendChild(d)}renderProfile();d.showModal()}
function renderProfile(){let p=profileDraft,i=profileId,d=$('#profileDialog');d.innerHTML=`<form id="profileForm"><div class="profile-modal-top"><div><span class="eyebrow">PROFIL PASUKAN · KUMPULAN ${teamGroup(i)}</span><h2>${esc(p.teamName)}</h2></div><button type="button" data-close-profile aria-label="Tutup profil">Tutup</button></div><div id="teamPlacement">${teamPlacementCard(i,p)}</div>${teamAnalytics(i)}${ADMIN?`<h3>Maklumat pasukan</h3><div class="profile-fields">${field('Nama pasukan',p.teamName,'teamName')}<label>Negeri / Wilayah${regionSelect(p.region,'region')}</label><div>${upload('Muat naik logo pasukan','logo')}</div><div>${upload('Muat naik bendera pasukan (pilihan)','flag')}</div></div><p class="note">PNG, JPG atau WebP, maksimum 2 MB. Logo pasukan diwarisi oleh semua pemain. Bendera negeri tersedia secara automatik.</p>`:''}<h3>Maklumat pemain</h3>${p.players.map((pl,j)=>`<section class="profile-player"><div class="player-heading">${playerPhoto(pl)}${teamLogo(i,p)}<div><b>Pemain ${j+1} ${p.captain===j?'· Kapten':''}</b><p>${esc(pl.role)} · #${esc(pl.number)}</p></div>${img(pl.flag||(pl.region?flagPath(pl.region):p.flag||flagPath(p.region)),'Bendera '+(pl.region||p.region),'state-flag')}</div>${ADMIN?`<div class="profile-fields">${field('Nama pemain',pl.name,'players.'+j+'.name')}<div class="player-photo-upload">${upload('Muat naik gambar pemain','players.'+j+'.photo')}<small>PNG, JPG atau WebP · Maksimum 2 MB</small></div>${drivePhotoField(pl,j)}${field('Nombor pemain',pl.number,'players.'+j+'.number','type="number" min="1" max="99" step="1"')}<label>Posisi<select data-field="players.${j}.role">${['Lead','Second','Skip'].map(r=>`<option ${pl.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Negeri pemain${regionSelect(pl.region,'players.'+j+'.region',true)}</label><div>${upload('Bendera pemain (pilihan)','players.'+j+'.flag')}</div></div>`:`<h3>${esc(pl.name)}</h3><p>${esc(pl.region||p.region)} · ${name(i)}</p>`}</section>`).join('')}${ADMIN?`<label class="captain-select">Kapten pasukan<select data-field="captain">${p.players.map((pl,j)=>`<option value="${j}" ${p.captain===j?'selected':''}>Pemain ${j+1} – ${esc(pl.name)}</option>`).join('')}</select></label><p id="profileError" role="alert"></p><div class="profile-save"><span class="note">Disimpan dalam pelayar admin ini.</span><button class="primary" type="submit">Simpan profil</button></div>`:''}</form>`;
bindTeamAnalytics();if(ADMIN)bindDrivePhotoButtons(d);bindPlayerButtons(d);d.querySelector('[data-close-profile]').onclick=()=>d.close();if(!ADMIN){$('#profileForm').onsubmit=e=>e.preventDefault();return}d.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{if(el.dataset.field.endsWith('.driveUrl')&&!el.value.trim())setDraft(el.dataset.field.replace(/\.driveUrl$/,'.photo'),'');setDraft(el.dataset.field,el.dataset.field==='captain'?+el.value:el.value)});d.querySelectorAll('[data-upload]').forEach(el=>el.onchange=()=>uploadImage(el));d.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{setDraft(b.dataset.remove,'');if(b.dataset.remove.endsWith('.photo'))setDraft(b.dataset.remove.replace(/\.photo$/,'.driveUrl'),'');renderProfile()});$('#profileForm').onsubmit=e=>{e.preventDefault();try{p.players.forEach(pl=>{if(pl.driveUrl?.trim())pl.photo=drivePhotoUrl(pl.driveUrl)})}catch(error){$('#profileError').textContent=error.message;return}let error='';let names=p.players.map(pl=>pl.name.trim().toLowerCase());if(!p.teamName.trim()||names.some(n=>!n))error='Nama pasukan dan ketiga-tiga pemain wajib diisi.';else if(new Set(names).size!==3)error='Nama ketiga-tiga pemain mesti berbeza.';else if(new Set(p.players.map(pl=>pl.role)).size!==3)error='Tetapkan seorang Lead, seorang Second dan seorang Skip.';else if(p.players.some(pl=>!Number.isInteger(+pl.number)||+pl.number<1||+pl.number>99)||new Set(p.players.map(pl=>+pl.number)).size!==3)error='Gunakan nombor pemain berbeza, antara 1 hingga 99.';if(error){$('#profileError').textContent=error;return}let prior=state.profiles[i],priorName=state.teams[i];state.profiles[i]=JSON.parse(JSON.stringify(p));state.profiles[i].players.forEach(pl=>pl.name=pl.name.trim());delete state.profiles[i].teamName;state.teams[i]=p.teamName.trim();try{localStorage.setItem(key,JSON.stringify(state))}catch{state.profiles[i]=prior;state.teams[i]=priorName;$('#profileError').textContent='Storan pelayar penuh. Gunakan imej yang lebih kecil.';return}d.close();render();toast('Profil pasukan dan 3 pemain disimpan')};}
function setDraft(path,value){let parts=path.split('.'),obj=profileDraft;for(let k=0;k<parts.length-1;k++)obj=obj[parts[k]];obj[parts.at(-1)]=value}
async function uploadImage(input){let f=input.files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>2*1024*1024){$('#profileError').textContent='Pilih PNG, JPG atau WebP berukuran maksimum 2 MB.';return}let url=URL.createObjectURL(f);try{let im=new Image();im.src=url;await im.decode();let canvas=document.createElement('canvas'),scale=Math.min(1,240/im.width,240/im.height);canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);if(input.dataset.upload.endsWith('.photo'))setDraft(input.dataset.upload.replace(/\.photo$/,'.driveUrl'),'');setDraft(input.dataset.upload,canvas.toDataURL('image/webp',.85));renderProfile()}catch{$('#profileError').textContent='Imej tidak dapat dibaca. Cuba fail lain.'}finally{URL.revokeObjectURL(url)}}

function drivePhotoUrl(value){let u;try{u=new URL(value.trim())}catch{throw Error('Masukkan pautan Google Drive yang sah.')}if(u.protocol!=='https:'||!['drive.google.com','www.drive.google.com'].includes(u.hostname)||u.username||u.password)throw Error('Gunakan pautan HTTPS daripada drive.google.com.');let id=u.pathname.match(/^\/file\/d\/([A-Za-z0-9_-]+)(?:\/|$)/)?.[1];if(!id&&['/open','/uc','/thumbnail'].includes(u.pathname))id=u.searchParams.get('id');if(!id||!/^[A-Za-z0-9_-]{10,200}$/.test(id))throw Error('Gunakan pautan fail gambar, bukan pautan folder Google Drive.');let target=new URL('https://drive.google.com/thumbnail');target.searchParams.set('id',id);target.searchParams.set('sz','w600');let resource=u.searchParams.get('resourcekey');if(resource)target.searchParams.set('resourcekey',resource);return target.href}
function drivePhotoField(pl,j){return `<div class="drive-photo-field"><label>Pautan Google Drive gambar pemain<input type="url" data-field="players.${j}.driveUrl" value="${esc(pl.driveUrl||'')}" maxlength="2048" placeholder="https://drive.google.com/file/d/…/view"></label><div class="drive-actions"><button type="button" data-drive-preview="${j}">Pratonton gambar Drive</button><button type="button" data-drive-remove="${j}">Padam pautan</button></div><small>Di Google Drive: Kongsi → Akses umum → Sesiapa sahaja yang mempunyai pautan → Pelihat. Gunakan fail gambar, bukan folder.</small></div>`}
function bindDrivePhotoButtons(d){d.querySelectorAll('[data-drive-preview]').forEach(b=>b.onclick=()=>{let pl=profileDraft.players[+b.dataset.drivePreview];try{pl.photo=drivePhotoUrl(pl.driveUrl||'');renderProfile()}catch(e){$('#profileError').textContent=e.message;$('#profileError').scrollIntoView({block:'nearest'})}});d.querySelectorAll('[data-drive-remove]').forEach(b=>b.onclick=()=>{let pl=profileDraft.players[+b.dataset.driveRemove];if(pl.driveUrl){pl.driveUrl='';pl.photo=''}renderProfile()})}
document.addEventListener('error',e=>{let im=e.target;if(im.tagName!=='IMG'||!im.classList.contains('player-photo'))return;let fallback=document.createElement('div');fallback.className=im.className+' photo-placeholder photo-unavailable';fallback.setAttribute('role','img');fallback.setAttribute('aria-label','Gambar pemain tidak dapat dimuatkan');fallback.innerHTML='<span>?</span><small>Gambar tidak tersedia</small>';fallback.title='Semak pautan, jenis fail gambar dan akses perkongsian Google Drive.';im.replaceWith(fallback)},true);

function playerPhoto(pl,large=false){let initials=pl.name.trim().split(/\s+/).slice(0,2).map(n=>n[0]||'').join('').toUpperCase();return pl.photo?`<button type="button" class="photo-view-button ${large?'large-photo-button':''}" data-photo-src="${esc(pl.photo)}" data-photo-name="${esc(pl.name)}" aria-label="Lihat gambar penuh ${esc(pl.name)}">${img(pl.photo,'Gambar '+pl.name,'player-photo'+(large?' large-photo':''))}${large?'<span>Lihat gambar penuh</span>':''}</button>`:`<div class="player-photo photo-placeholder ${large?'large-photo':''}" role="img" aria-label="Gambar belum dimuat naik untuk ${esc(pl.name)}"><span>${esc(initials)}</span><small>Gambar pemain</small></div>`}
function editPlayerPhoto(i,j){openProfile(i);let row=$('#profileDialog').querySelectorAll('.profile-player')[j];row?.scrollIntoView({block:'start',behavior:'smooth'});row?.querySelector('[data-upload$=".photo"]')?.focus({preventScroll:true})}
function openPhotoView(src,playerName){let d=$('#photoDialog');if(!d){d=document.createElement('dialog');d.id='photoDialog';d.setAttribute('aria-labelledby','photoViewTitle');document.body.appendChild(d)}d.innerHTML=`<div class="profile-modal-top"><div><span class="eyebrow">GAMBAR PEMAIN</span><h2 id="photoViewTitle">${esc(playerName)}</h2></div><button type="button" id="closePhotoView">Tutup</button></div><div class="full-photo-stage">${img(src,'Gambar '+playerName,'player-photo full-photo')}</div><p class="note">Gambar dipaparkan mengikut nisbah asal.</p>`;$('#closePhotoView').onclick=()=>d.close();d.showModal()}
document.addEventListener('click',e=>{let button=e.target.closest?.('[data-photo-src]');if(button)openPhotoView(button.dataset.photoSrc,button.dataset.photoName)});

function bindPlayerButtons(scope=document){scope.querySelectorAll('[data-photo-edit]').forEach(b=>b.onclick=()=>{let [i,j]=b.dataset.photoEdit.split(':').map(Number);editPlayerPhoto(i,j)});scope.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{let [i,j]=b.dataset.player.split(':').map(Number);openPlayer(i,j)})}

function fixtureTeams(match){const team=id=>id==null?'<div class="fixture-pending">Menunggu kelayakan</div>':summaryTeam(id);return `<div class="fixture-teams">${team(match.a)}<span class="fixture-versus">lwn</span>${team(match.b)}</div>`}
function summaryTeam(id){return `<div class="summary-team">${teamLogo(id)}${teamFlag(id)}<strong>${name(id)}</strong></div>`}
let schedulePage=0,standingsGroup='all';
function overview64(){const done=state.matches.filter(m=>m.score).length,final=state.matches.find(m=>m.group==='F'),winner=final.score?(final.score[0]>final.score[1]?final.a:final.b):null;return `<div class="stats"><div class="stat"><label>Pasukan bertanding</label><strong>64</strong><small>8 kumpulan × 8 pasukan</small></div><div class="stat"><label>Perlawanan selesai</label><strong>${done}<span style="font-size:1rem"> / 256</span></strong><small>224 round robin + 32 kalah mati</small></div><div class="stat"><label>Layak kalah mati</label><strong>32</strong><small>Top 4 setiap kumpulan</small></div><div class="stat"><label>Rink demo</label><strong>08</strong><small>13 ends · 90 minit</small></div><div class="stat tournament-ends-stat"><label>Jumlah Ends dimainkan</label><strong>${tournamentEnds().total}</strong><small>${tournamentEnds().regular} biasa + ${tournamentEnds().extra} extra · Perlawanan dikira sekali</small></div></div><div class="hero"><div><div class="eyebrow">KEPUTUSAN DEMO · AKHIR</div><h2>${winner==null?'Menanti juara':name(winner)+' menjuarai gelanggang.'}</h2><p>64 pasukan. 8 kumpulan. Satu juara.</p><button data-go="schedule-bracket">Lihat kalah mati & bracket</button></div><div class="bowls" aria-hidden="true"><div class="bowl"></div><div class="bowl second"></div><div class="jack"></div></div></div><div class="section-title"><h2>Kedudukan 8 kumpulan</h2><button data-go="standings">Lihat semua kedudukan</button></div>${GROUPS.map((g,i)=>`<details class="overview-group" ${i===0?'open':''}><summary>Kumpulan ${g} · 8 pasukan · Top 4 layak</summary>${groupTable(g)}</details>`).join('')}<div class="section-title"><div><h2>Jadual demo</h2><p>28 Januari–1 Februari 2027 · 8 rink · 256 perlawanan</p></div><button data-go="schedule">Lihat jadual penuh</button></div>${matchTable(state.matches.slice(0,8))}`}
function progressiveTable(g){return `<article class="panel progressive"><div class="panel-head"><h3>Progresif · Kumpulan ${g}</h3></div><div class="table-wrap"><table><thead><tr><th>Pasukan</th>${Array.from({length:7},(_,r)=>`<th>Pusingan ${r+1}</th>`).join('')}<th>Mata</th></tr></thead><tbody>${standings(g).map(r=>`<tr><th>${summaryTeam(r.id)}</th>${Array.from({length:7},(_,round)=>{let m=state.matches.find(m=>m.group==='G'+g&&m.round===round+1&&(m.a===r.id||m.b===r.id)),side=m.a===r.id?0:1;return `<td><button data-edit="${m.id}" class="progressive-score ${m.score?m.score[side]>m.score[1-side]?'menang':m.score[side]<m.score[1-side]?'kalah':'seri':''}">${m.score?m.score[side]+' – '+m.score[1-side]:'—'}<small>Remarks</small></button></td>`}).join('')}<td>${r.pts}</td></tr>`).join('')}</tbody></table></div></article>`}
let scheduleScope='all',scheduleLayout='list',scheduleStage='all',scheduleDate='all';
function unifiedMatches(){return state.matches.filter(m=>(scheduleScope==='all'||scheduleScope==='group'&&isGroup(m.group)||scheduleScope==='ko'&&!isGroup(m.group))&&(scheduleStage==='all'||scheduleStage===m.group)&&(scheduleDate==='all'||scheduleDate===m.date))}
function unifiedPageControls(matches,pages,position='top'){const start=matches.length?schedulePage*16+1:0,end=Math.min((schedulePage+1)*16,matches.length);return `<div class="schedule-pagination unified-pagination ${position==='bottom'?'pagination-bottom':''}"><span>${start}–${end} daripada ${matches.length} perlawanan · Halaman ${schedulePage+1}/${pages}</span><div><button type="button" data-u-page="prev" ${schedulePage===0?'disabled':''}>Sebelum</button><button type="button" data-u-page="next" ${schedulePage>=pages-1?'disabled':''}>Seterusnya</button></div></div>`}
function unifiedScheduleView(){const all=state.matches.length,league=state.matches.filter(m=>isGroup(m.group)).length,ko=all-league;const scopeButtons=[['all','Semua',all],['group','Kumpulan',league],['ko','Kalah Mati',ko]];const dates=[...new Set(state.matches.map(m=>m.date))].sort();const groupOptions=GROUPS.map(g=>`<option value="G${g}" ${scheduleStage==='G'+g?'selected':''}>Kumpulan ${g}</option>`).join(''),koOptions=knockoutRounds.map(([id,title])=>`<option value="${id}" ${scheduleStage===id?'selected':''}>${title}</option>`).join('');const matches=unifiedMatches(),pages=Math.max(1,Math.ceil(matches.length/16));schedulePage=Math.max(0,Math.min(schedulePage,pages-1));return `<div class="section-title unified-title"><div><h2>Jadual & Keputusan</h2><p>28 Januari–1 Februari 2027 · 64 pasukan · 8 rink</p></div><span class="unified-total">${state.matches.filter(m=>m.score).length}/${all} selesai</span></div><div class="unified-switchbar"><div class="unified-scopes" role="group" aria-label="Kategori perlawanan">${scopeButtons.map(([id,title,count])=>`<button type="button" data-u-scope="${id}" class="${scheduleScope===id?'active':''}" aria-pressed="${scheduleScope===id}">${title}<span>${count}</span></button>`).join('')}</div><div class="unified-layout" role="group" aria-label="Jenis paparan"><button type="button" data-u-layout="list" class="${scheduleLayout==='list'?'active':''}" aria-pressed="${scheduleLayout==='list'}">Senarai</button><button type="button" data-u-layout="bracket" class="${scheduleLayout==='bracket'?'active':''}" aria-pressed="${scheduleLayout==='bracket'}">Bracket</button></div></div>${scheduleLayout==='bracket'?`<div class="unified-bracket-note"><b>Bracket kalah mati</b><span>Top 4 setiap kumpulan mara ke Top 32. Tekan perlawanan untuk Remarks.</span></div>${knockoutBracket()}`:`<div class="unified-filters"><label>Peringkat / kumpulan<select id="unifiedStage"><option value="all">${scheduleScope==='group'?'Semua kumpulan':scheduleScope==='ko'?'Semua kalah mati':'Semua peringkat'}</option>${scheduleScope!=='ko'?`<optgroup label="Peringkat kumpulan">${groupOptions}</optgroup>`:''}${scheduleScope!=='group'?`<optgroup label="Kalah mati">${koOptions}</optgroup>`:''}</select></label><label>Tarikh<select id="unifiedDate"><option value="all">Semua tarikh</option>${dates.map(date=>{const d=matchDateInfo({date});return `<option value="${date}" ${scheduleDate===date?'selected':''}>${d.date} (${d.day})</option>`}).join('')}</select></label><button type="button" class="unified-clear" id="unifiedReset">Reset penapis</button></div><div class="unified-results-summary"><strong>${scheduleStage!=='all'?label({group:scheduleStage}):scheduleScope==='group'?'Peringkat kumpulan':scheduleScope==='ko'?'Peringkat kalah mati':'Semua perlawanan'}</strong><span>${matches.filter(m=>m.score).length}/${matches.length} selesai</span></div>${unifiedPageControls(matches,pages)}${matches.length?scheduleCards(matches.slice(schedulePage*16,(schedulePage+1)*16),'',false):'<div class="ko-no-matches"><h3>Tiada perlawanan</h3><p>Cuba tarikh atau peringkat lain, atau reset penapis.</p></div>'}${matches.length>16?unifiedPageControls(matches,pages,'bottom'):''}<details class="unified-break-info"><summary>Waktu permainan & rehat</summary><p>10:00 pagi–10:30 malam. Rehat hari biasa: 1:00–1:30 petang. Jumaat, 29 Januari: rehat khas 11:30 pagi–2:00 petang. Top 32 pada 31 Januari, 7:30 dan 9:00 malam. Top 16 hingga akhir pada 1 Februari, 10:00 pagi–4:30 petang.</p></details>`}`}
function bindUnifiedSchedule(){document.querySelectorAll('[data-u-scope]').forEach(b=>b.onclick=()=>{scheduleScope=b.dataset.uScope;scheduleStage='all';scheduleDate='all';schedulePage=0;if(scheduleScope!=='ko')scheduleLayout='list';render()});document.querySelectorAll('[data-u-layout]').forEach(b=>b.onclick=()=>{scheduleLayout=b.dataset.uLayout;if(scheduleLayout==='bracket'){scheduleScope='ko';scheduleStage='all';scheduleDate='all';schedulePage=0}render()});if($('#unifiedStage'))$('#unifiedStage').onchange=e=>{scheduleStage=e.target.value;if(scheduleStage!=='all')scheduleScope=isGroup(scheduleStage)?'group':'ko';schedulePage=0;render()};if($('#unifiedDate'))$('#unifiedDate').onchange=e=>{scheduleDate=e.target.value;schedulePage=0;render()};if($('#unifiedReset'))$('#unifiedReset').onclick=()=>{scheduleScope='all';scheduleStage='all';scheduleDate='all';schedulePage=0;render()};document.querySelectorAll('[data-u-page]').forEach(b=>b.onclick=()=>{schedulePage+=b.dataset.uPage==='next'?1:-1;render();$('#content').scrollIntoView({block:'start',behavior:'smooth'})});if(scheduleLayout==='bracket')bindKnockout()}

function render(){if(view==='bracket'){view='schedule';scheduleLayout='bracket';scheduleScope='ko'}ensureProfiles();sync();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let html='';if(view==='overview')html=overview64();if(view==='schedule')html=unifiedScheduleView();if(view==='standings')html=`<div class="section-title"><div><h2>Kedudukan kumpulan</h2><p>8 kumpulan · 8 pasukan setiap kumpulan · Top 4 layak ke Top 32</p></div></div><div class="tabs">${['all',...GROUPS].map(g=>`<button data-standing="${g}" class="${standingsGroup===g?'active':''}">${g==='all'?'Semua':'Kumpulan '+g}</button>`).join('')}</div>${GROUPS.filter(g=>standingsGroup==='all'||g===standingsGroup).map(g=>groupTable(g)+`<details class="overview-group"><summary>Lihat progresif Kumpulan ${g}</summary>${progressiveTable(g)}</details>`).join('')}<p class="note">Susunan: mata liga, beza shot, jumlah shot, kemudian kod pasukan jika masih sama. Menang 2 mata, seri 1 mata, kalah 0 mata. Top 4 ditandakan hijau.</p>`;if(view==='teams')html=roster();$('#content').classList.toggle('schedule-view',view==='schedule');$('#content').innerHTML=html;if(view==='schedule')bindUnifiedSchedule();if(view==='teams')bindRoster();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openMatch(b.dataset.edit));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;schedulePage=0;render()});document.querySelectorAll('[data-standing]').forEach(b=>b.onclick=()=>{standingsGroup=b.dataset.standing;render()});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{schedulePage+=b.dataset.page==='next'?1:-1;render();$('#content').scrollIntoView({block:'start',behavior:'smooth'})})}
function go(v){if(v==='bracket'||v==='schedule-bracket'){view='schedule';scheduleLayout='bracket';scheduleScope='ko';scheduleStage='all';scheduleDate='all';schedulePage=0}else view=v;render();window.scrollTo({top:0,behavior:'smooth'})}
function endPointsInfo(pair,prev,side){if(!pair||pair.some(v=>v==null||v==='')) return {text:'',tone:''};const base=prev&&prev[side]!=null&&prev[side]!==''?+prev[side]:0;const gain=+pair[side]-base;const tone=endsOutcome(pair,side)==='draw'?'draw':gain>0?'win':'lose';return {text:gain>0?'+'+gain:'-',tone}}function endPointsTag(pair,prev,side){const {text,tone}=endPointsInfo(pair,prev,side);return `<span class="end-points tone-${tone}" aria-hidden="true">${text}</span>`}function endsOutcome(pair,side){if(!pair||pair.some(v=>v==null||v===''))return 'pending';return +pair[side]>+pair[1-side]?'win':+pair[side]<+pair[1-side]?'lose':'draw'}
function endsResultLabel(type){return {win:'Menang',lose:'Kalah',draw:'Seri',pending:'Belum ada skor'}[type]}
function endsSummary(match,score=match.score){return `<div class="ends-summary">${[match.a,match.b].map((id,side)=>{const type=endsOutcome(score,side);return `<div class="ends-team result-${type}"><div class="ends-team-brand">${teamLogo(id)}${teamFlag(id)}</div><strong class="ends-team-name">${name(id)}</strong><span class="ends-big-score">${score?.[side]??'—'}</span><span class="ends-result-tag">${endsResultLabel(type)}</span></div>`}).join('')}</div>`}
function endRow(index,pair){const m=editing;return `<tr><td class="ends-number"><b>${index<13?index+1:'E'+(index-12)}</b></td>${[0,1].map(side=>{const pts=`<td class="ends-pts-cell">${endPointsTag(pair,editing.ends?.[index-1],side)}</td>`;const score=`<td class="ends-value result-${endsOutcome(pair,side)}" data-ends-side="${side}">${ADMIN?`<input aria-label="${name(side===0?m.a:m.b)}, ends ${index+1}" data-end="${index}" data-side="${side}" type="number" min="0" max="999" step="1" value="${pair?.[side]??''}" required>`:`<b>${pair?.[side]??'—'}</b>`}<span class="sr-only">${endsResultLabel(endsOutcome(pair,side))}</span></td>`;return side===0?pts+score:score+pts}).join('')}</tr>`}
function refreshEndsPreview(){if(!ADMIN)return;const rows=[...$('#endsBody').querySelectorAll('tr')];const pairAt=i=>[...rows[i].querySelectorAll('[data-end]')].map(el=>el.value===''?null:Number(el.value));rows.forEach((row,ri)=>{const inputs=[...row.querySelectorAll('[data-end]')];const pair=inputs.map(el=>el.value===''?null:Number(el.value));row.querySelectorAll('.end-points').forEach((el,side)=>{{const info=endPointsInfo(pair,ri?pairAt(ri-1):null,side);el.textContent=info.text;el.className='end-points tone-'+info.tone}});row.querySelectorAll('[data-ends-side]').forEach((td,side)=>{const type=endsOutcome(pair,side);td.className='ends-value result-'+type;td.querySelector('.sr-only').textContent=endsResultLabel(type)})});let inputs=[...$('#endsBody').querySelectorAll('[data-end]')].slice(-2);let pair=inputs.length===2?inputs.map(el=>el.value===''?null:Number(el.value)):null;if(!isGroup(editing.group)&&rows.length===13&&pair&&pair.every(v=>v!=null)&&pair[0]===pair[1]){$('#endsBody').insertAdjacentHTML('beforeend',endRow(13));pair=null;toast('Seri selepas Ends 13. Extra Ends 14 ditambah.')}if($('#extraEnd'))$('#extraEnd').disabled=!pair||pair.some(v=>v==null)||pair[0]!==pair[1];$('#endsHero').innerHTML=endsSummary(editing,pair)}
function openMatch(id){editing=state.matches.find(m=>m.id===id);if(!editing||editing.a==null||editing.b==null)return;const m=editing;$('#matchTitle').textContent='Keputusan perlawanan';$('#scoreError').textContent='';$('#scoreForm').querySelector('.scoreFields').outerHTML=`<div class="scoreFields ends-content"><div class="ends-caption">Keputusan akhir · Jumlah shot</div><div id="endsHero" aria-live="polite">${endsSummary(m)}</div>${matchInfo(m)}<div class="ends-table-heading"><h3>13 Ends${m.ends?.length>13?' + '+(m.ends.length-13)+' extra':''}</h3><span>Skor terkumpul</span></div><div class="table-wrap end-scroll ends-table-wrap"><table class="ends-table"><thead><tr><th scope="col" rowspan="2" class="ends-label">Ends</th>${[m.a,m.b].map(team=>`<th scope="col" colspan="2"><span class="ends-column-brand" aria-label="${name(team)}">${teamLogo(team)}${teamFlag(team)}</span></th>`).join('')}</tr><tr><th scope="col" class="ends-sub ends-sub-pts">+Mata</th><th scope="col" class="ends-sub">Skor</th><th scope="col" class="ends-sub">Skor</th><th scope="col" class="ends-sub ends-sub-pts">+Mata</th></tr></thead><tbody id="endsBody">${Array.from({length:Math.max(13,m.ends?.length||0)},(_,i)=>endRow(i,m.ends?.[i])).join('')}</tbody></table></div><div class="ends-points-legend"><span class="end-points tone-win">+n</span> mendapat point<span class="end-points tone-lose">-</span> tiada point tambahan<span class="end-points tone-draw">seri</span></div>${ADMIN&&!isGroup(m.group)?'<button type="button" id="extraEnd">Tambah extra ends</button>':''}<div class="ends-legend"><span class="legend-win">Menang</span><span class="legend-draw">Seri</span><span class="legend-lose">Kalah</span></div></div>`;if(ADMIN){if(!isGroup(m.group)&&m.ends?.length===13&&m.ends[12][0]===m.ends[12][1])$('#endsBody').insertAdjacentHTML('beforeend',endRow(13));$('#matchDateInput').onchange=e=>{const value=e.target.value;$('#matchDay').textContent=validMatchDate(value)?matchDateInfo({date:value}).day:'—'};$('#endsBody').oninput=refreshEndsPreview;if($('#extraEnd'))$('#extraEnd').onclick=()=>{let index=$('#endsBody').children.length;$('#endsBody').insertAdjacentHTML('beforeend',endRow(index));$('#endsBody').lastElementChild.scrollIntoView({block:'nearest'});refreshEndsPreview()}}if(ADMIN&&$('#extraEnd'))$('#extraEnd').disabled=!m.ends?.length||m.ends.at(-1)[0]!==m.ends.at(-1)[1];$('#editor').showModal()}
$('#scoreForm').onsubmit=e=>{e.preventDefault();const date=$('#matchDateInput').value;if(!validMatchDate(date)){$('#scoreError').textContent='Pilih tarikh perlawanan yang sah.';return}let inputs=[...document.querySelectorAll('[data-end]')],ends=[];for(let i=0;i<inputs.length;i+=2){let pair=[Number(inputs[i].value),Number(inputs[i+1].value)];if(pair.some(x=>!Number.isInteger(x)||x<0||x>999)){ $('#scoreError').textContent='Skor mesti nombor bulat 0–999.';return}if(ends.length&&pair.some((x,j)=>x<ends.at(-1)[j])){$('#scoreError').textContent='Skor terkumpul tidak boleh berkurang (ends '+(i/2+1)+').';return}ends.push(pair)}let last=ends.at(-1);if(!isGroup(editing.group)&&last[0]===last[1]){$('#scoreError').textContent='Keputusan seri. Tambah extra ends untuk menentukan pemenang.';return}let changed=JSON.stringify(last)!==JSON.stringify(editing.score);editing.date=date;editing.ends=ends;editing.score=last;sync();save();$('#editor').close();render();toast('Keputusan 13 ends disimpan')};
$('#cancel').onclick=()=>$('#editor').close();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{go(b.dataset.view);closeMenu()});const burger=document.querySelector('#menuToggle');function closeMenu(){document.querySelector('aside')?.classList.remove('menu-open');burger?.setAttribute('aria-expanded','false')}if(burger)burger.onclick=()=>{const open=document.querySelector('aside').classList.toggle('menu-open');burger.setAttribute('aria-expanded',String(open))};$('#print').onclick=()=>window.print();$('#reset').onclick=()=>{if(confirm('Pulihkan semua nama team dan keputusan dummy? Perubahan dalam pelayar ini akan diganti.')){state=seed();save();render();toast('Data demo dipulihkan')}};
$('#export').onclick=()=>{let rows=[['No. perlawanan','Tarikh','Hari','Peringkat','Masa','Rink','Team 1','Team 2','Ends','Skor terkumpul 1','Skor terkumpul 2']];state.matches.forEach(m=>(m.ends||Array.from({length:13},()=>['',''])).forEach((e,i)=>rows.push([matchNumber(m),matchDateInfo(m).date,matchDateInfo(m).day,label(m),m.time,m.rink,state.teams[m.a]||'',state.teams[m.b]||'',i+1,...e])));let csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='jadual-lawn-bowls-13-ends.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};render();

function openPlayersAnchor(){if(['#pasukan','#pemain'].includes(location.hash)){go('teams')}else if(location.hash==='#jadual'){go('schedule')}else if(location.hash==='#bracket'){go('schedule-bracket')}}window.addEventListener('hashchange',openPlayersAnchor);openPlayersAnchor();

$('#editor').onclose=()=>{if($('#profileDialog')?.open)refreshTeamAnalytics()};
